type Props = { projectId?: string; product: { id: string; name: string; purpose: string; revision: number }; principalId: string; api: PreparationApi; onSaved: () => void | Promise<void> };
type Receipt = { id: string; subject_type: string; subject_id: string };
const operationKinds = { assembly: "装配", inspection: "检验", test: "测试", packaging: "包装", other: "其他" };
const designNames = { mechanical: "机械设计版本", electronic: "电子设计版本", firmware: "固件制品版本" };
const resourceKinds = { person: "人员", equipment: "设备", tooling: "工装 / 工具", station: "工位", other: "其他" };
const emptyConfigurations: ConfigurationList = { boms: [], engineering: [], processes: [], unavailable_count: 0, has_more: false };
const fieldNames: Record<string, string> = {
  name: "名称", purpose: "用途", scope: "范围", visibility: "可见范围", revision: "版本", status: "状态", type: "轮次类型",
  definition: "固定型号定义", bom: "固定 BOM", engineering_configuration: "固定工程配置", manufacturing_configuration: "固定制造配置", project: "所属项目", project_name: "所属项目", lines: "BOM 物料行", part: "固定物料", quantity: "每件用量", unit: "单位", loss_rate: "损耗率", critical: "关键件", notes: "说明", key: "行 / 工序标识", internal_number: "内部研发编号", erp_number: "外部 ERP 料号", customer_number: "客户料号", mapping_version: "编号映射版本", external_design_refs: "外部设计引用", system: "外部系统", external_id: "外部编号", as_of: "截至时间", content_sha256: "内容摘要", basis: "原文依据", sources: "原文依据", expected_revision: "来源版本", line: "原文行", quote: "精确摘录", reason: "保存原因", operations: "工序", kind: "类型", depends_on: "前置工序", sop: "作业文件固定引用", resource_requirements: "资源要求", qualification: "资格要求", cycle_time_minutes: "节拍（分钟）", acceptance_criterion: "验收判据", previous: "前版", after: "确认后保存", before: "当前记录", planned_quantity: "计划数量", planned_start: "计划开始", planned_end: "计划结束", verification_objectives: "验证目标", disposition_plan: "实物处置要求", build: "Build 计划", effect: "此次操作影响", owner_name: "负责人", definition_revision: "固定定义版本", bom_revision: "固定 BOM 版本", engineering_revision: "固定工程版本", manufacturing_revision: "固定制造版本", applicability: "适用范围", title: "标题",
};
Object.assign(fieldNames, { design_versions: "机械 / 电子 / 固件固定版本", ...designNames, site: "制造场地", bom_line_keys: "关联 BOM 行", external_verification: "外部系统核验", mapping_status: "编号映射状态", qualification_status: "制造专业资格" });
const hiddenFields = new Set(["id", "product_id", "tenant_id", "owner_id", "actor_id", "requester_id", "operation", "confirmation_token", "required_source_read_set", "created_at", "expected_previous_revision", "previous_id", "artifact_id", "part_id", "definition_id", "bom_id", "engineering_configuration_id", "manufacturing_configuration_id", "project_id", "previous_build_id", "expected_definition_revision", "expected_bom_revision", "expected_engineering_revision", "expected_project_revision", "expected_build_revision", "content_hash", "input_sha256", "schema_version", "algorithm"]);
const valueNames: Record<string, string> = { private: "仅本人", product: "品类授权成员", draft: "草稿，尚未发布", planned: "固定计划 · 执行状态见开工办理", known: "已明确", unknown: "未知，待补充", blocked: "有阻塞", not_checked: "尚未核验外部系统", declared: "人工声明，尚未核验", current: "来源当前有效", needs_recheck: "来源待重核", prototype: "原型验证", tool_trial: "试模 / 工装试验", pilot: "试产验证", ...operationKinds, ...resourceKinds };

const translatedFields = new Set(["status", "visibility", "type", "kind", "external_verification", "mapping_status", "qualification_status", "source_status"]);

function DetailValue({ value, sourceNames, translate = false }: { value: unknown; sourceNames?: Map<string, string>; translate?: boolean }) {
  if (value === null || value === undefined || value === "") return <span className="subtle">尚未明确</span>;
  if (typeof value === "boolean") return <span>{value ? "是" : "否"}</span>;
  if (typeof value === "string") return <span className="whitespace-pre-wrap [overflow-wrap:anywhere]">{translate ? valueNames[value] ?? value : value}</span>;
  if (typeof value === "number") return <span>{value}</span>;
  if (Array.isArray(value)) return value.length ? <ol className="space-y-3">{value.map((item, index) => <li key={index} className="min-w-0 rounded-lg border border-border p-3"><DetailValue value={item} sourceNames={sourceNames} translate={translate}/></li>)}</ol> : <span className="subtle">未声明</span>;
  if (typeof value === "object") {
    const reference = value as Record<string, unknown>;
    if (typeof reference.artifact_id === "string" && typeof reference.quote === "string" && typeof reference.line === "number") return <blockquote className="min-w-0 border-l-2 border-primary pl-3 text-sm"><p className="font-medium [overflow-wrap:anywhere]">{sourceNames?.get(reference.artifact_id) ?? `固定资料 · ${reference.artifact_id}`} · v{String(reference.expected_revision)} · 第 {reference.line} 行</p><p className="mt-1 whitespace-pre-wrap [overflow-wrap:anywhere]">{reference.quote}</p></blockquote>;
    return <dl className="min-w-0 space-y-3">{Object.entries(value).filter(([key]) => !hiddenFields.has(key) && fieldNames[key]).map(([key, item]) => <div key={key} className="min-w-0"><dt className="subtle mb-1">{key === "line" ? "制造产线" : fieldNames[key]}</dt><dd className="min-w-0 text-sm"><DetailValue value={item} sourceNames={sourceNames} translate={translatedFields.has(key)}/></dd></div>)}</dl>;
  }
  return null;
}

function ExternalFields({ value, refs, onChange, title }: { value: ExternalDraft; refs: DefinitionReference[]; onChange: (next: ExternalDraft) => void; title: string }) {
  return <fieldset className="min-w-0 rounded-lg border border-border p-3"><legend className="px-1 text-sm font-medium">{title}</legend><div className="grid min-w-0 gap-x-3 sm:grid-cols-2"><label>系统名称<input maxLength={80} value={value.system} onChange={event => onChange({ ...value, system: event.target.value })} placeholder="例如 PLM、CAD、文件管理"/></label><label>外部编号<input maxLength={200} value={value.externalId} onChange={event => onChange({ ...value, externalId: event.target.value })}/></label><label>明确版本<input maxLength={100} value={value.revision} onChange={event => onChange({ ...value, revision: event.target.value })}/></label><label>截至时间（UTC，未知可空）<input type="datetime-local" step="0.001" value={value.asOfUtc} onChange={event => onChange({ ...value, asOfUtc: event.target.value })}/></label></div><label>内容摘要（未核验可空）<input maxLength={64} value={value.hash} onChange={event => onChange({ ...value, hash: event.target.value })}/></label><label>精确原文依据<select value={value.referenceKey} onChange={event => onChange({ ...value, referenceKey: event.target.value })}><option value="">选择本次已加入的原文依据</option>{refs.map((ref, index) => <option key={referenceKey(ref)} value={referenceKey(ref)}>{index + 1}. 第 {ref.line} 行 · {ref.quote.slice(0, 70)}</option>)}</select></label><p className="subtle">版本、截至时间或摘要缺失时，必须用精确原文说明采用的外部版本；链接本身不证明版本。</p></fieldset>;
}

function RevisionFields({ value, previous, allowShared, onChange, onPrevious }: { value: RevisionDraft; previous: ConfigurationBase[]; allowShared: boolean; onChange: (next: Partial<RevisionDraft>) => void; onPrevious: (id: string) => void }) {
  const historical = (item: ConfigurationBase) => !!item.series_id && previous.some(other => other.series_id === item.series_id && other.revision > item.revision);
  return <><label>固定前版<select value={value.previousId} onChange={event => onPrevious(event.target.value)}><option value="">创建首版</option>{previous.map(item => <option key={item.id} value={item.id} disabled={item.source_status === "needs_recheck" || historical(item)}>{item.name} · v{item.revision}{historical(item) ? " · 历史版，续版须选当前版" : item.source_status === "needs_recheck" ? " · 来源待重核" : ""}</option>)}</select></label><label>名称<input maxLength={200} value={value.name} onChange={event => onChange({ name: event.target.value })}/></label><label>可见范围<select value={value.visibility} onChange={event => onChange({ visibility: event.target.value as RevisionDraft["visibility"] })}><option value="private">仅本人</option><option value="product" disabled={!allowShared}>品类授权成员</option></select></label>{!allowShared && <p className="subtle mb-3">本次包含私人来源或私人固定版本，整组配置仅本人可见。</p>}<label>此次保存原因<textarea maxLength={2000} value={value.reason} onChange={event => onChange({ reason: event.target.value })}/></label></>;
}

function Readiness({ build, materialNames }: { build: Build; materialNames: Map<string, string> }) {
  const stale = build.source_status === "needs_recheck" || build.engineering_configuration.source_status === "needs_recheck" || build.manufacturing_configuration.source_status === "needs_recheck" || build.readiness?.is_current === false;
  if (!build.readiness) return <p className="subtle">{stale ? "固定来源已失效或撤回，需要先重核配置；尚未计算准备缺项。" : "尚未计算准备缺项。"}计划配置已经固定，尚未获得本轮开工授权。</p>;
  const result = build.readiness.result;
  const fixedBom = build.engineering_configuration.bom as BomConfiguration | undefined;
  const fixedNames = new Map(fixedBom?.lines.flatMap(line => [[line.part.id, line.part.name], [line.key, line.part.name]] as [string, string][]) ?? []);
  return <section className="min-w-0 space-y-3" aria-label={`${build.name}准备缺项`}>{stale && <p role="status" className="rounded-lg border border-destructive p-3 text-destructive">此历史结果依据已失效或撤回，需要重核。下列检查保留原计算时点的结论，不表示当前有效；当前不能继续计算或开工。</p>}<div className="rounded-lg border border-primary bg-muted/40 p-3"><p className="flex items-start gap-2 font-medium"><WarningCircle className="mt-0.5 shrink-0 text-primary"/>准备仍有未知或阻塞，尚不能据此开工</p><p className="subtle mt-2">此次结果固定于 {utcText(result.as_of)}。同一固定输入保留原计算结果，不重复生成新快照。未记录真实供应、资源、品质方法或专业放行的事实继续保留未知。</p></div>{result.checks.map(check => <article key={check.key} className="min-w-0 rounded-lg border border-border p-3"><p className="break-words font-medium">{check.label} · {valueNames[check.status]}</p><p className="mt-2 break-words text-sm">{check.message}</p><p className="mt-2 break-words text-sm">下一步：{check.recovery_action}</p>{check.source_refs.length > 0 && <p className="subtle mt-2">固定依据：{check.source_refs.map(ref => `${({ build: "本轮计划", bom: "BOM", bom_revision: "BOM", engineering_configuration: "工程配置", process_revision: "制造配置", manufacturing_configuration: "制造配置", definition_revision: "型号定义", project: "项目" } as Record<string, string>)[ref.kind] ?? "固定记录"} v${ref.revision}`).join("；")}</p>}</article>)}{result.demands.length > 0 && <details className="min-w-0 rounded-lg border border-border p-3"><summary className="cursor-pointer font-medium">本轮物料需求 · {result.demands.length} 行</summary><div className="mt-3 space-y-3">{result.demands.map((demand, index) => <article key={demand.item_id} className="min-w-0 border-t border-border pt-3"><p className="break-words font-medium">{fixedNames.get(demand.material_id) ?? fixedNames.get(demand.item_id) ?? materialNames.get(demand.material_id) ?? materialNames.get(demand.item_id) ?? `物料行 ${index + 1}`}{demand.critical ? " · 关键件" : ""}</p><p className="mt-1 min-w-0 text-sm [overflow-wrap:anywhere]">每件用量：{decimalText(demand.quantity_per_product)} {demand.unit ?? "单位待确认"}</p><p className="mt-1 min-w-0 text-sm [overflow-wrap:anywhere]">计划需求：{decimalText(demand.required_quantity)} {demand.unit ?? "单位待确认"}</p>{demand.issues.length > 0 && <p className="subtle mt-2">用量、损耗、单位或供应事实仍需补充，未用 0 代替未知。</p>}</article>)}</div><p className="subtle mt-3">需求计算不等于齐套。供方承诺、库存记录与实际可用物料需各自有事实依据。</p></details>}</section>;
}

export function BuildPreparation(props: Props) { return <PreparationPanel key={`${props.principalId}:${props.product.id}:${props.projectId ?? ""}`} {...props}/>; }

function PreparationPanel({ product, principalId, api, onSaved, projectId = "" }: Props) {
  const storageKey = `pdos-next:build-preparation:${principalId}:${product.id}${projectId ? `:project:${projectId}` : ""}`;
  const [draft, setDraft] = useState(() => { const value = blankPreparation(product.purpose); value.build.projectId = projectId; return value; });
  const [configurations, setConfigurations] = useState<ConfigurationList>(emptyConfigurations);
  const [projects, setProjects] = useState<Project[]>([]);
  const [definitions, setDefinitions] = useState<DefinitionRevision[]>([]);
  const [sources, setSources] = useState<DefinitionSource[]>([]);
  const [builds, setBuilds] = useState<Build[]>([]);
  const [pending, setPending] = useState<WaitingPreparation | null>(null);
  const [preview, setPreview] = useState<PreparationPreview | null>(null);
  const [busy, setBusy] = useState(false);
  const [ready, setReady] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [rejected, setRejected] = useState(false);
  const [hidden, setHidden] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [sourceId, setSourceId] = useState("");
  const [line, setLine] = useState(1);
  const [quote, setQuote] = useState("");
  const alive = useRef(true), lock = useRef(false);
  const dialog = useRef<HTMLDialogElement>(null), trigger = useRef<HTMLElement | null>(null);
  const editable = ready && !busy && !pending && !preview;
  const source = sources.find(item => item.id === sourceId);
  const sourceNames = new Map(sources.map(source => [source.id, source.title]));
  const definition = definitions.find(item => item.id === draft.engineering.definitionId);
  const engineeringBom = configurations.boms.find(item => item.id === draft.engineering.bomId);
  const processEngineering = configurations.engineering.find(item => item.id === draft.process.engineeringId);
  const buildProject = projects.find(item => item.id === draft.build.projectId);
  const buildEngineering = configurations.engineering.find(item => item.id === draft.build.engineeringId);
  const buildManufacturing = configurations.processes.find(item => item.id === draft.build.manufacturingId);
  const allSourcesShared = draft.references.every(ref => sources.find(item => item.id === ref.artifact_id)?.visibility === "category");
  const reusedParts = new Map(configurations.boms.flatMap(bom => bom.lines.map(line => [line.part.id, line.part] as const)));
  const allReusedPartsShared = draft.bom.lines.every(line => !line.partId || reusedParts.get(line.partId)?.visibility === "category");
  const materialNames = new Map(configurations.boms.flatMap(bom => bom.lines.map(line => [line.part.id, line.part.name] as [string, string])));

  const refresh = useCallback(async () => {
    const results = await Promise.allSettled([
      api<ConfigurationList>(`v1/products/${product.id}/configurations`), api<ProjectList>(projectId ? `v1/products/${product.id}/projects/${projectId}` : `v1/products/${product.id}/projects`), api<BuildList>(projectBuildsPath(product.id, projectId)), api<DefinitionList>(`v1/products/${product.id}/definitions`), api<{ sources: DefinitionSource[] }>(`v1/products/${product.id}/workspace`),
    ]);
    if (!alive.current) return;
    const failures: string[] = []; let unavailable = 0, more = false;
    const configured = results[0];
    if (configured.status === "fulfilled") { setConfigurations(configured.value); unavailable += configured.value.unavailable_count; more ||= configured.value.has_more; }
    else { setConfigurations(emptyConfigurations); failures.push(configured.reason?.message ?? "配置暂时无法读取。"); }
    const projected = results[1];
    if (projected.status === "fulfilled") { setProjects(projected.value.items); unavailable += projected.value.unavailable_count; more ||= projected.value.has_more; }
    else { setProjects([]); failures.push(projected.reason?.message ?? "项目暂时无法读取。"); }
    const built = results[2];
    if (built.status === "fulfilled") { setBuilds(built.value.items); unavailable += built.value.unavailable_count; more ||= built.value.has_more; }
    else { setBuilds([]); failures.push(built.reason?.message ?? "Build 暂时无法读取。"); }
    const defined = results[3];
    if (defined.status === "fulfilled") { setDefinitions(defined.value.items); unavailable += defined.value.unavailable_count; more ||= defined.value.has_more; }
    else { setDefinitions([]); failures.push(defined.reason?.message ?? "型号定义暂时无法读取。"); }
    const workspace = results[4];
    if (workspace.status === "fulfilled") setSources(workspace.value.sources);
    else { setSources([]); failures.push(workspace.reason?.message ?? "原文依据暂时无法读取。"); }
    setHidden(unavailable); setHasMore(more); setLoading(false);
    if (failures.length) throw new Error(failures.join(" "));
  }, [api, product.id, projectId]);
  useEffect(() => {
    alive.current = true;
    void Promise.resolve().then(() => { if (alive.current) return refresh(); }).catch(failure => { if (alive.current) setError(failure.message); });
    void Promise.resolve().then(() => {
      if (!alive.current) return;
      try { const local = restorePreparation(JSON.parse(localStorage.getItem(storageKey) ?? "null"), product.id); if (local) { setDraft(local.draft); setPending(local.pending); } } catch { /* Local storage never grants server permissions. */ }
      setReady(true);
    });
    return () => { alive.current = false; };
  }, [refresh, storageKey, product.id]);
  useEffect(() => { if (preview) dialog.current?.showModal(); }, [preview]);
  function remember(next: PreparationDraft, waiting: WaitingPreparation | null) { try { localStorage.setItem(storageKey, JSON.stringify({ draft: next, pending: waiting })); } catch { /* Online actions remain available. */ } }
  function edit(next: PreparationDraft) { setDraft(next); remember(next, pending); }
  function waitFor(waiting: WaitingPreparation | null) { setPending(waiting); remember(draft, waiting); }
  function closePreview() { dialog.current?.close(); setPreview(null); trigger.current?.focus(); }
  function command(operation: PreparationOperation, payload: PreparationCommand["payload"], reads: SourceRead[]): PreparationCommand { return { command_id: crypto.randomUUID(), idempotency_key: crypto.randomUUID(), operation, product_id: product.id, expected_revision: product.revision, source_read_set: mergeReadSets(reads), payload }; }
  async function run(waiting: WaitingPreparation, element?: HTMLElement) {
    if (lock.current) return;
    if (projectId && waiting.command.operation === "build.create" && (!("project_id" in waiting.command.payload) || waiting.command.payload.project_id !== projectId)) {
      setError("原请求属于其他项目，请返回对应项目核对；当前项目未提交。");
      return;
    }
    lock.current = true; setBusy(true); setError(""); setNotice(""); setRejected(false);
    if (element) trigger.current = element;
    waitFor(waiting); let committed = false;
    try {
      const request = waiting.command;
      if (waiting.stage === "preview") {
        const result = await api<PreparationPreview>("v1/commands/preview", request);
        if (!result.command || result.command.product_id !== product.id || result.command.command_id !== request.command_id || result.command.idempotency_key !== request.idempotency_key || result.command.operation !== request.operation || !result.confirmation_token || result.command.payload["confirmation_token" as keyof typeof result.command.payload] !== result.confirmation_token || !result.review?.effect || !result.review.name || (request.operation === "build.create" ? !result.review.engineering_configuration || !result.review.manufacturing_configuration || !result.review.project_name : !result.review.after)) throw new Error("预览内容尚未确认，请按原请求重新核对范围。");
        if (!alive.current) return;
        waitFor(null); setPreview(result);
      } else {
        const receipt = await api<Receipt>("v1/commands", request);
        if (!receipt.id || receipt.subject_type !== preparationReceiptTypes[request.operation] || !receipt.subject_id) throw new Error("保存回执尚未确认，请按原请求重试。");
        committed = true; if (!alive.current) return;
        waitFor(null); closePreview();
        if (request.operation === "engineering.bom.revise") { const next = { ...draft, engineering: { ...draft.engineering, bomId: receipt.subject_id } }; setDraft(next); remember(next, null); }
        if (request.operation === "engineering.configuration.create") { const next = { ...draft, process: { ...draft.process, engineeringId: receipt.subject_id }, build: { ...draft.build, engineeringId: receipt.subject_id, manufacturingId: "" } }; setDraft(next); remember(next, null); }
        if (request.operation === "npi.process.revise") { const next = { ...draft, build: { ...draft.build, engineeringId: String(request.payload["engineering_configuration_id" as keyof typeof request.payload] ?? draft.build.engineeringId), manufacturingId: receipt.subject_id } }; setDraft(next); remember(next, null); }
        setNotice(request.operation === "build.readiness.compute" ? "固定输入下的准备结果已核对。原计算时间与结果保留，未知与阻塞不构成开工授权。" : `${preparationNames[request.operation]}已保存，固定版本和原文依据保留。尚未发布或开工。`);
        await refresh(); await onSaved();
      }
    } catch (failure) {
      if (!alive.current) return;
      const failed = failure as Error & { status?: number };
      if (!committed) setRejected([400, 401, 403, 404, 409, 422].includes(failed.status ?? 0));
      if (!committed && waiting.stage === "execute") closePreview();
      if (failed.status === 401 || failed.status === 403) { setConfigurations(emptyConfigurations); setBuilds([]); setDefinitions([]); setProjects([]); setSources([]); }
      setError(committed ? `保存已完成；最新结果读取失败，可刷新。${failed.message}` : failed.message);
    } finally { lock.current = false; if (alive.current) setBusy(false); }
  }
  function attempt(action: () => void) { setError(""); try { action(); } catch (failure) { setError((failure as Error).message); } }
  function inheritedReferences(...values: (ConfigurationBase | DefinitionRevision | undefined)[]): DefinitionReference[] { return [...new Map([...draft.references, ...values.flatMap(value => value?.sources ?? [])].map(ref => [referenceKey(ref), plainReference(ref)])).values()]; }
  function startBom(element: HTMLElement) { attempt(() => { const previous = configurations.boms.find(item => item.id === draft.bom.previousId), refs = inheritedReferences(previous); const parts = draft.bom.lines.filter(line => !!line.partId).map(line => { const part = reusedParts.get(line.partId); if (!part || part.revision !== line.partRevision) throw new Error("复用物料的固定版本当前不可读，请重新选择可见 BOM 前版。"); return part; }); const payload: BomPayload = { ...revisionPayload(draft.bom, previous, refs), lines: bomLinesPayload(draft.bom.lines, refs) }; void run({ stage: "preview", command: command("engineering.bom.revise", payload, mergeReadSets(previous?.required_source_read_set ?? [], ...parts.map(part => part.required_source_read_set), referencesReadSet(refs))) }, element); }); }
  function startEngineering(element: HTMLElement) { attempt(() => { if (!definition || !engineeringBom) throw new Error("请先选择真实定义和已保存 BOM。"); const previous = configurations.engineering.find(item => item.id === draft.engineering.previousId), refs = inheritedReferences(previous, definition, engineeringBom); const payload: EngineeringPayload = { ...revisionPayload(draft.engineering, previous, refs), definition_id: definition.id, expected_definition_revision: definition.revision, bom_id: engineeringBom.id, expected_bom_revision: engineeringBom.revision, mechanical: externalPayload(draft.engineering.designs.mechanical, refs), electronic: externalPayload(draft.engineering.designs.electronic, refs), firmware: externalPayload(draft.engineering.designs.firmware, refs) }; void run({ stage: "preview", command: command("engineering.configuration.create", payload, mergeReadSets(previous?.required_source_read_set ?? [], engineeringBom.required_source_read_set, referencesReadSet(refs))) }, element); }); }
  function startProcess(element: HTMLElement) { attempt(() => { if (!processEngineering) throw new Error("请先选择真实工程配置。"); if (draft.process.operations.some(operation => operation.bomLineKeys.some(key => !processEngineering.bom.lines.some(line => line.key === key)))) throw new Error("部分关联 BOM 行不属于所选工程配置，请逐工序重新核对关联。"); const previous = configurations.processes.find(item => item.id === draft.process.previousId), refs = inheritedReferences(previous, processEngineering); const payload: ProcessPayload = { ...revisionPayload(draft.process, previous, refs), engineering_configuration_id: processEngineering.id, expected_engineering_revision: processEngineering.revision, site: draft.process.site.trim() || null, line: draft.process.line.trim() || null, operations: operationsPayload(draft.process.operations, refs) }; void run({ stage: "preview", command: command("npi.process.revise", payload, mergeReadSets(previous?.required_source_read_set ?? [], processEngineering.required_source_read_set, referencesReadSet(refs))) }, element); }); }
  function startBuild(element: HTMLElement) { attempt(() => { if (projectId && draft.build.projectId !== projectId) throw new Error("请选择当前项目的试制计划。"); if (!buildProject || !buildEngineering || !buildManufacturing) throw new Error("请先逐级选择真实项目、工程配置和制造配置。"); if (buildProject.owner_id !== principalId) throw new Error("当前首版责任范围仅允许项目负责人建立 Build。"); const payload = createBuildPayload(draft.build, buildProject, buildEngineering, buildManufacturing); void run({ stage: "preview", command: command("build.create", payload, mergeReadSets(buildProject.required_source_read_set, buildEngineering.required_source_read_set, buildManufacturing.required_source_read_set)) }, element); }); }
  function compute(build: Build) { attempt(() => { void run({ stage: "execute", command: command("build.readiness.compute", { build_id: build.id, expected_build_revision: build.revision }, build.required_source_read_set) }); }); }
  function changeBom(patch: Partial<BomDraft>) { edit({ ...draft, bom: { ...draft.bom, ...patch } }); }
  function changeLine(index: number, patch: Partial<BomLineDraft>) { changeBom({ lines: draft.bom.lines.map((line, position) => position === index ? { ...line, ...patch } : line) }); }
  function changeOperation(index: number, patch: Partial<OperationDraft>) { edit({ ...draft, process: { ...draft.process, operations: draft.process.operations.map((operation, position) => position === index ? { ...operation, ...patch } : operation) } }); }
  function selectBomPrevious(id: string) {
    const previous = configurations.boms.find(item => item.id === id);
    if (!previous) { changeBom({ previousId: "" }); return; }
    changeBom({ name: previous.name, previousId: previous.id, visibility: previous.visibility, reason: "", lines: previous.lines.map(line => ({ key: line.key, partId: line.part.id, partRevision: line.part.revision, name: line.part.name, internal: line.part.internal_number ?? "", erp: line.part.erp_number ?? "", customer: line.part.customer_number ?? "", mappingVersion: line.part.mapping_version ?? "", quantity: line.quantity ?? "", unit: line.unit ?? "", loss: line.loss_rate ?? "", critical: line.critical, notes: line.notes ?? "", designRefs: [] })) });
  }
  function selectProcessPrevious(id: string) {
    const previous = configurations.processes.find(item => item.id === id);
    if (!previous) { edit({ ...draft, process: { ...draft.process, previousId: "" } }); return; }
    const operations = previous.operations;
    if (!Array.isArray(operations)) { setError("前版工序内容不完整，请刷新后再续版。"); return; }
    edit({ ...draft, process: { ...draft.process, name: previous.name, previousId: previous.id, visibility: previous.visibility, reason: "", engineeringId: previous.engineering_configuration_id, site: previous.site ?? "", line: previous.line ?? "", operations: operations.map(operation => ({ key: operation.key, name: operation.name, kind: operation.kind, dependencies: operation.depends_on.join("、"), bomLineKeys: [...operation.bom_line_keys], cycle: operation.cycle_time_minutes ?? "", acceptance: operation.acceptance_criterion ?? "", notes: operation.notes ?? "", sop: externalDraft(operation.sop), resources: operation.resource_requirements.map(resource => ({ kind: resource.kind, name: resource.name, externalId: resource.external_id ?? "", qualification: resource.qualification ?? "" })) })) }, references: inheritedReferences(previous) });
  }

  return <section className="min-w-0 space-y-5" aria-label="工程制造配置与Build准备">
    <header className="flex flex-wrap items-start justify-between gap-3"><div><p className="subtle">固定双配置，准备有明确目的的实物验证</p><h2 className="mt-1 text-lg font-semibold">配置与 Build 准备</h2></div><Button variant="outline" disabled={busy || !!preview} onClick={() => { setError(""); void refresh().catch(failure => setError(failure.message)); }}><ArrowClockwise/>刷新配置与轮次</Button></header>
    {error && <p role="alert" className="break-words rounded-lg border border-destructive p-3 text-destructive">{error}</p>}
    {notice && <p role="status" className="break-words rounded-lg border border-border p-3">{notice}</p>}
    {pending && <section className="min-w-0 rounded-lg border border-primary p-4"><p className="font-medium">{pending.stage === "preview" ? "范围核对结果待确认" : "本次保存结果待确认"}</p><p className="subtle mt-2">输入和原请求已保留。重试使用同一请求和版本；确认结果前不新建另一请求。</p><div className="mt-3 flex flex-wrap gap-2"><Button disabled={busy} onClick={() => void run(pending)}>按原请求重试</Button>{(pending.stage === "preview" || rejected) && <Button variant="outline" disabled={busy} onClick={() => { waitFor(null); setRejected(false); closePreview(); }}>保留输入，返回编辑</Button>}</div></section>}
    {loading && <p className="subtle" role="status">正在读取当前可见定义、项目、配置和 Build…</p>}
    {hidden > 0 && <p className="subtle">{hidden} 条关联内容的来源权限需要重核，正文暂时隐藏。</p>}
    {hasMore && <p className="subtle">当前显示最近可见记录；历史版本保留。</p>}
    <div className="grid min-w-0 items-start gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <div className="min-w-0 space-y-5">
        <details className="panel" open><summary className="cursor-pointer font-semibold">本次配置的原文依据 · {draft.references.length} 条</summary><fieldset className="mt-4 min-w-0" disabled={!editable || loading}><label>当前资料<select value={sourceId} onChange={event => { setSourceId(event.target.value); setQuote(""); setLine(1); }}><option value="">选择资料</option>{sources.map(item => <option key={item.id} value={item.id} disabled={item.status !== "active"}>{item.title} · {item.visibility === "private" ? "仅本人" : "品类共享"}</option>)}</select></label>{source && <div className="mb-3 max-h-52 min-w-0 overflow-auto">{sourceLines(source.content).map((text, index) => <button type="button" className="source-line" key={index} disabled={!text.trim() || source.status !== "active"} aria-pressed={line === index + 1 && !!quote && text.includes(quote)} onClick={() => { setLine(index + 1); setQuote(text.slice(0, 4000)); }}><span className="subtle shrink-0">{index + 1}</span><span className="min-w-0 [overflow-wrap:anywhere]">{text}</span></button>)}</div>}<label>精确摘录 · 第 {line} 行<textarea maxLength={4000} value={quote} onChange={event => setQuote(event.target.value)}/></label><Button type="button" variant="outline" disabled={!source || !quote.trim()} onClick={() => { if (!source || !sourceLines(source.content)[line - 1]?.includes(quote.trim())) { setError("摘录须能在所选原文行精确定位。"); return; } const ref = { artifact_id: source.id, expected_revision: source.revision, line, quote: quote.trim() }; edit({ ...draft, references: [...new Map([...draft.references, ref].map(item => [referenceKey(item), item])).values()], ...(source.visibility === "private" ? { bom: { ...draft.bom, visibility: "private" }, engineering: { ...draft.engineering, visibility: "private" }, process: { ...draft.process, visibility: "private" } } : {}) }); }}><Plus/>加入本次依据</Button><ul className="mt-3 min-w-0 space-y-3">{draft.references.map(ref => <li key={referenceKey(ref)} className="min-w-0 text-sm"><p className="[overflow-wrap:anywhere]">{sources.find(item => item.id === ref.artifact_id)?.title ?? "固定原文"} · v{ref.expected_revision} · 第 {ref.line} 行：{ref.quote}</p><Button type="button" size="sm" variant="ghost" onClick={() => edit({ ...draft, references: draft.references.filter(item => referenceKey(item) !== referenceKey(ref)) })}><Trash/>移除依据</Button></li>)}</ul><p className="subtle mt-3">从前版、定义与配置继承的原文仍完整固定；这里补充本轮依据。私人依据不会扩大受众。</p></fieldset></details>
        <details className="panel" open={configurations.boms.length === 0}><summary className="cursor-pointer font-semibold">1 · BOM 物料版本</summary><form className="mt-4 min-w-0" noValidate onSubmit={event => { event.preventDefault(); startBom(event.currentTarget.querySelector<HTMLButtonElement>('button[type="submit"]') ?? event.currentTarget); }}><fieldset disabled={!editable || loading} className="min-w-0"><RevisionFields value={draft.bom} previous={configurations.boms} allowShared={allSourcesShared && allReusedPartsShared && configurations.boms.find(item => item.id === draft.bom.previousId)?.visibility !== "private"} onChange={changeBom} onPrevious={selectBomPrevious}/><p className="subtle mb-4">研发编号、ERP 料号与客户料号分别记录。未知用量、单位和损耗保持空值。</p><div className="space-y-4">{draft.bom.lines.map((item, index) => <section key={index} className="min-w-0 rounded-lg border border-border p-3"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><h3 className="font-medium">物料行 {index + 1}{item.partId ? ` · 固定物料 v${item.partRevision}` : " · 新物料草稿"}</h3><Button type="button" size="sm" variant="ghost" disabled={draft.bom.lines.length === 1} onClick={() => changeBom({ lines: draft.bom.lines.filter((_, position) => position !== index) })}><Trash/>移除行</Button></div><label>行标识<input maxLength={80} value={item.key} onChange={event => changeLine(index, { key: event.target.value })}/></label><label>物料名称<input maxLength={200} value={item.name} disabled={!!item.partId} onChange={event => changeLine(index, { name: event.target.value })}/></label>{item.partId ? <p className="subtle mb-3">沿用固定物料和设计引用。需要不同物料时，新增一行；续版不会改写旧物料。</p> : <><details className="mb-3"><summary className="cursor-pointer text-sm font-medium">编号映射与外部设计引用</summary><div className="mt-3"><label>内部研发编号<input value={item.internal} onChange={event => changeLine(index, { internal: event.target.value })}/></label><label>ERP 外部料号<input value={item.erp} onChange={event => changeLine(index, { erp: event.target.value })}/></label><label>客户料号<input value={item.customer} onChange={event => changeLine(index, { customer: event.target.value })}/></label><label>编号映射版本<input value={item.mappingVersion} onChange={event => changeLine(index, { mappingVersion: event.target.value })}/></label><div className="space-y-3">{item.designRefs.map((ref, position) => <div key={position}><ExternalFields value={ref} refs={draft.references} title={`设计引用 ${position + 1}`} onChange={next => changeLine(index, { designRefs: item.designRefs.map((old, offset) => offset === position ? next : old) })}/><Button type="button" size="sm" variant="ghost" onClick={() => changeLine(index, { designRefs: item.designRefs.filter((_, offset) => offset !== position) })}><Trash/>移除此引用</Button></div>)}</div><Button type="button" className="mt-3" variant="outline" size="sm" onClick={() => changeLine(index, { designRefs: [...item.designRefs, blankExternal()] })}><Plus/>加入固定设计引用</Button></div></details></>}<div className="grid gap-x-3 sm:grid-cols-2"><label>每件用量（未知可空）<input inputMode="decimal" value={item.quantity} onChange={event => changeLine(index, { quantity: event.target.value })}/></label><label>单位（未知可空）<input maxLength={80} value={item.unit} onChange={event => changeLine(index, { unit: event.target.value })}/></label><label>损耗率（0–1，未知可空）<input inputMode="decimal" value={item.loss} onChange={event => changeLine(index, { loss: event.target.value })} placeholder="0.05 表示 5%"/></label><label>关键件<select value={item.critical ? "yes" : "no"} onChange={event => changeLine(index, { critical: event.target.value === "yes" })}><option value="no">未声明为关键件</option><option value="yes">本轮明确为关键件</option></select></label></div><label>物料行说明<textarea value={item.notes} onChange={event => changeLine(index, { notes: event.target.value })}/></label></section>)}</div><Button type="button" variant="outline" className="my-4" disabled={draft.bom.lines.length >= 200} onClick={() => { let index = draft.bom.lines.length + 1; while (draft.bom.lines.some(item => item.key === `line-${index}`)) index += 1; changeBom({ lines: [...draft.bom.lines, blankBomLine(index)] }); }}><Plus/>加入物料行</Button><div><Button type="submit"><Cube/>查看 BOM 保存范围…</Button></div></fieldset></form></details>
        <details className="panel" open={configurations.engineering.length === 0 && configurations.boms.length > 0}><summary className="cursor-pointer font-semibold">2 · 工程配置</summary><form className="mt-4" noValidate onSubmit={event => { event.preventDefault(); startEngineering(event.currentTarget.querySelector<HTMLButtonElement>('button[type="submit"]') ?? event.currentTarget); }}><fieldset disabled={!editable || loading} className="min-w-0"><RevisionFields value={draft.engineering} previous={configurations.engineering} allowShared={allSourcesShared && definition?.visibility === "category" && engineeringBom?.visibility === "category" && configurations.engineering.find(item => item.id === draft.engineering.previousId)?.visibility !== "private"} onChange={patch => edit({ ...draft, engineering: { ...draft.engineering, ...patch } })} onPrevious={id => { const previous = configurations.engineering.find(item => item.id === id); edit({ ...draft, engineering: { ...draft.engineering, previousId: id, ...(previous ? { name: previous.name, visibility: previous.visibility, definitionId: previous.definition_id, bomId: previous.bom_id, reason: "", designs: { mechanical: externalDraft(previous.design_versions.mechanical), electronic: externalDraft(previous.design_versions.electronic), firmware: externalDraft(previous.design_versions.firmware) } } : {}) }, references: inheritedReferences(previous) }); }}/><label>固定型号定义<select value={draft.engineering.definitionId} onChange={event => edit({ ...draft, engineering: { ...draft.engineering, definitionId: event.target.value, ...(definitions.find(item => item.id === event.target.value)?.visibility === "private" ? { visibility: "private" } : {}) } })}><option value="">选择真实定义草稿</option>{definitions.map(item => <option key={item.id} value={item.id} disabled={item.source_status !== "current"}>{item.title} · v{item.revision}</option>)}</select></label><label>固定 BOM<select value={draft.engineering.bomId} onChange={event => edit({ ...draft, engineering: { ...draft.engineering, bomId: event.target.value, ...(configurations.boms.find(item => item.id === event.target.value)?.visibility === "private" ? { visibility: "private" } : {}) } })}><option value="">选择已保存 BOM 版本</option>{configurations.boms.map(item => <option key={item.id} value={item.id} disabled={item.source_status === "needs_recheck"}>{item.name} · v{item.revision}</option>)}</select></label><details className="mb-4 min-w-0"><summary className="cursor-pointer text-sm font-medium">机械 / 电子 / 固件固定版本（未明确可空）</summary><div className="mt-3 space-y-3">{(Object.keys(designNames) as (keyof typeof designNames)[]).map(key => <ExternalFields key={key} value={draft.engineering.designs[key]} refs={inheritedReferences(configurations.engineering.find(item => item.id === draft.engineering.previousId), definition, engineeringBom)} title={designNames[key]} onChange={next => edit({ ...draft, engineering: { ...draft.engineering, designs: { ...draft.engineering.designs, [key]: next } } })}/>)}</div></details><p className="subtle mb-3">固定所选定义和 BOM，后续新版本不会自动替换本配置。当前草稿仍需专业确认。</p><Button type="submit">查看工程配置保存范围…</Button></fieldset></form></details>
        <details className="panel" open={configurations.processes.length === 0 && configurations.engineering.length > 0}><summary className="cursor-pointer font-semibold">3 · 制造配置与工序</summary><form className="mt-4 min-w-0" noValidate onSubmit={event => { event.preventDefault(); startProcess(event.currentTarget.querySelector<HTMLButtonElement>('button[type="submit"]') ?? event.currentTarget); }}><fieldset disabled={!editable || loading} className="min-w-0"><RevisionFields value={draft.process} previous={configurations.processes} allowShared={allSourcesShared && processEngineering?.visibility === "category" && configurations.processes.find(item => item.id === draft.process.previousId)?.visibility !== "private"} onChange={patch => edit({ ...draft, process: { ...draft.process, ...patch } })} onPrevious={selectProcessPrevious}/><label>固定工程配置<select value={draft.process.engineeringId} onChange={event => edit({ ...draft, process: { ...draft.process, engineeringId: event.target.value, ...(configurations.engineering.find(item => item.id === event.target.value)?.visibility === "private" ? { visibility: "private" } : {}) } })}><option value="">选择已保存工程配置</option>{configurations.engineering.map(item => <option key={item.id} value={item.id} disabled={item.source_status === "needs_recheck"}>{item.name} · v{item.revision}</option>)}</select></label><div className="grid gap-x-3 sm:grid-cols-2"><label>制造场地（未明确可空）<input maxLength={200} value={draft.process.site} onChange={event => edit({ ...draft, process: { ...draft.process, site: event.target.value } })}/></label><label>制造产线（未明确可空）<input maxLength={200} value={draft.process.line} onChange={event => edit({ ...draft, process: { ...draft.process, line: event.target.value } })}/></label></div><p className="subtle mb-4">制造配置独立续版，固定采用的工程版。工时、资源可用性和专业资格未确认时保持未知。</p><div className="space-y-4">{draft.process.operations.map((operation, index) => <section key={index} className="min-w-0 rounded-lg border border-border p-3"><div className="mb-3 flex flex-wrap justify-between gap-2"><h3 className="font-medium">工序 {index + 1}</h3><Button type="button" variant="ghost" size="sm" disabled={draft.process.operations.length === 1} onClick={() => edit({ ...draft, process: { ...draft.process, operations: draft.process.operations.filter((_, position) => position !== index) } })}><Trash/>移除工序</Button></div><label>工序标识<input maxLength={80} value={operation.key} onChange={event => changeOperation(index, { key: event.target.value })}/></label><label>工序名称<input maxLength={200} value={operation.name} onChange={event => changeOperation(index, { name: event.target.value })}/></label><label>类型<select value={operation.kind} onChange={event => changeOperation(index, { kind: event.target.value as OperationDraft["kind"] })}>{Object.entries(operationKinds).map(([key, title]) => <option key={key} value={key}>{title}</option>)}</select></label><label>前置工序标识（逗号分隔）<input value={operation.dependencies} onChange={event => changeOperation(index, { dependencies: event.target.value })} placeholder="无前置时留空"/></label><fieldset className="mb-3 min-w-0 rounded-lg border border-border p-3"><legend className="px-1 text-sm font-medium">关联所选工程配置的 BOM 行</legend>{processEngineering?.bom.lines.map(line => <label key={line.key} className="flex items-start gap-2"><input type="checkbox" className="!mt-1 !w-auto shrink-0" checked={operation.bomLineKeys.includes(line.key)} onChange={event => changeOperation(index, { bomLineKeys: event.target.checked ? [...operation.bomLineKeys, line.key] : operation.bomLineKeys.filter(key => key !== line.key) })}/><span className="min-w-0 break-words">{line.part.name} · {line.key}</span></label>)}{!processEngineering && <p className="subtle">先选择工程配置再关联物料行。</p>}{operation.bomLineKeys.some(key => !processEngineering?.bom.lines.some(line => line.key === key)) && <p className="text-sm text-destructive">有继承的关联不属于当前工程版：{operation.bomLineKeys.filter(key => !processEngineering?.bom.lines.some(line => line.key === key)).join("；")}<Button type="button" size="sm" variant="outline" className="mt-2" onClick={() => changeOperation(index, { bomLineKeys: operation.bomLineKeys.filter(key => processEngineering?.bom.lines.some(line => line.key === key)) })}>移除不适用的关联</Button></p>}</fieldset><label>节拍分钟（未知可空）<input inputMode="decimal" value={operation.cycle} onChange={event => changeOperation(index, { cycle: event.target.value })}/></label><label>验收判据（待确认可空）<textarea value={operation.acceptance} onChange={event => changeOperation(index, { acceptance: event.target.value })}/></label><details className="mb-3"><summary className="cursor-pointer text-sm font-medium">固定作业文件与资源要求</summary><div className="mt-3 space-y-3"><ExternalFields value={operation.sop} refs={inheritedReferences(configurations.processes.find(item => item.id === draft.process.previousId), processEngineering)} title="作业文件引用（未明确可全部留空）" onChange={sop => changeOperation(index, { sop })}/>{operation.resources.map((resource, position) => <fieldset key={position} className="min-w-0 rounded-lg border border-border p-3"><legend className="px-1 text-sm">资源要求 {position + 1}</legend><label>资源类型<select value={resource.kind} onChange={event => changeOperation(index, { resources: operation.resources.map((old, offset) => offset === position ? { ...old, kind: event.target.value as typeof resource.kind } : old) })}>{Object.entries(resourceKinds).map(([key, title]) => <option key={key} value={key}>{title}</option>)}</select></label>{([ ["name", "资源名称"], ["externalId", "外部编号（可空）"], ["qualification", "资格 / 校准要求（可空）"] ] as const).map(([key, title]) => <label key={key}>{title}<input value={resource[key]} onChange={event => changeOperation(index, { resources: operation.resources.map((old, offset) => offset === position ? { ...old, [key]: event.target.value } : old) })}/></label>)}<Button type="button" size="sm" variant="ghost" onClick={() => changeOperation(index, { resources: operation.resources.filter((_, offset) => offset !== position) })}><Trash/>移除要求</Button></fieldset>)}<Button type="button" size="sm" variant="outline" onClick={() => changeOperation(index, { resources: [...operation.resources, { kind: "equipment", name: "", externalId: "", qualification: "" }] })}><Plus/>加入资源要求</Button></div></details><label>工序说明<textarea value={operation.notes} onChange={event => changeOperation(index, { notes: event.target.value })}/></label></section>)}</div><Button type="button" variant="outline" className="my-4" disabled={draft.process.operations.length >= 200} onClick={() => { let index = draft.process.operations.length + 1; while (draft.process.operations.some(item => item.key === `operation-${index}`)) index += 1; edit({ ...draft, process: { ...draft.process, operations: [...draft.process.operations, blankOperation(index)] } }); }}><Plus/>加入工序</Button><div><Button type="submit">查看制造配置保存范围…</Button></div></fieldset></form></details>
      </div>
      <div className="min-w-0 space-y-5">
        <section className="panel"><h3 className="font-semibold">4 · 计划本轮 Build</h3><p className="subtle mt-2">一次有明确用途、双配置、数量、验证目标和实物处置的活动。保存计划后再计算准备缺项。</p><form className="mt-4 min-w-0" noValidate onSubmit={event => { event.preventDefault(); startBuild(event.currentTarget.querySelector<HTMLButtonElement>('button[type="submit"]') ?? event.currentTarget); }}><fieldset disabled={!editable || loading} className="min-w-0"><label>所属项目<select value={draft.build.projectId} disabled={!!projectId} onChange={event => edit({ ...draft, build: { ...draft.build, projectId: event.target.value, engineeringId: "", manufacturingId: "", previousId: "" } })}><option value="">选择已建立的研发项目</option>{projects.map(item => <option key={item.id} value={item.id} disabled={item.source_status !== "current" || item.owner_id !== principalId}>{item.name}{item.owner_id !== principalId ? " · 当前负责人可建轮次" : ""} · 固定定义 v{item.definition.revision}</option>)}</select></label><label>计划工程配置<select value={draft.build.engineeringId} onChange={event => edit({ ...draft, build: { ...draft.build, engineeringId: event.target.value, manufacturingId: "" } })}><option value="">选择与项目固定定义一致的配置</option>{configurations.engineering.filter(item => item.definition_id === buildProject?.definition.id).map(item => <option key={item.id} value={item.id} disabled={item.source_status === "needs_recheck"}>{item.name} · v{item.revision}</option>)}</select></label><label>计划制造配置<select value={draft.build.manufacturingId} onChange={event => edit({ ...draft, build: { ...draft.build, manufacturingId: event.target.value } })}><option value="">选择明确采用上述工程版的制造配置</option>{configurations.processes.filter(item => item.engineering_configuration_id === buildEngineering?.id).map(item => <option key={item.id} value={item.id} disabled={item.source_status === "needs_recheck"}>{item.name} · v{item.revision}</option>)}</select></label>{buildProject && <p className="subtle mb-3">仅当前项目负责人可建立本轮计划。本轮固定该项目的定义 v{buildProject.definition.revision}，不自动采用“最新”配置。整轮受众由关联对象最窄范围决定。</p>}<label>轮次名称<input maxLength={160} value={draft.build.name} onChange={event => edit({ ...draft, build: { ...draft.build, name: event.target.value } })}/></label><label>轮次类型<select value={draft.build.type} onChange={event => edit({ ...draft, build: { ...draft.build, type: event.target.value as typeof draft.build.type } })}>{Object.entries(buildTypeNames).map(([key, title]) => <option key={key} value={key}>{title}</option>)}</select></label><label>本轮用途<textarea maxLength={2000} value={draft.build.purpose} onChange={event => edit({ ...draft, build: { ...draft.build, purpose: event.target.value } })}/></label><div className="grid gap-x-3 sm:grid-cols-2"><label>计划数量<input inputMode="decimal" value={draft.build.quantity} onChange={event => edit({ ...draft, build: { ...draft.build, quantity: event.target.value } })}/></label><label>单位<input maxLength={80} value={draft.build.unit} onChange={event => edit({ ...draft, build: { ...draft.build, unit: event.target.value } })}/></label><label>计划开始（UTC，未知可空）<input type="datetime-local" value={draft.build.startUtc} onChange={event => edit({ ...draft, build: { ...draft.build, startUtc: event.target.value } })}/></label><label>计划结束（UTC，未知可空）<input type="datetime-local" value={draft.build.endUtc} onChange={event => edit({ ...draft, build: { ...draft.build, endUtc: event.target.value } })}/></label></div><label>本轮验证目标<textarea maxLength={4000} value={draft.build.objectives} onChange={event => edit({ ...draft, build: { ...draft.build, objectives: event.target.value } })}/></label><label>样件、剩余物料与异常品的处置要求<textarea maxLength={4000} value={draft.build.disposition} onChange={event => edit({ ...draft, build: { ...draft.build, disposition: event.target.value } })}/></label><label>前一轮 Build<select value={draft.build.previousId} onChange={event => edit({ ...draft, build: { ...draft.build, previousId: event.target.value } })}><option value="">本项目首轮 / 无前轮关系</option>{builds.filter(item => item.project_id === draft.build.projectId).map(item => <option key={item.id} value={item.id}>{item.name} · {buildTypeNames[item.type]}</option>)}</select></label><Button type="submit"><ClipboardText/>查看本轮计划范围…</Button></fieldset></form></section>
        <section className="panel"><h3 className="font-semibold">已保存 Build 与准备缺项 · {builds.length} 轮</h3>{!loading && builds.length === 0 && <p className="subtle mt-3">尚无可见 Build。请先固定工程与制造配置，再创建本轮计划。</p>}<div className="mt-4 min-w-0 space-y-5">{builds.map(build => <article key={build.id} className="min-w-0 space-y-4 border-t border-border pt-4"><div><h4 className="break-words font-semibold">{build.name}</h4><p className="subtle mt-1">{build.project_name} · {buildTypeNames[build.type]} · 固定计划 · 执行状态见开工办理 · {build.visibility === "private" ? "仅本人" : "品类授权成员"}</p><p className="mt-2 break-words">{build.purpose}</p></div><dl className="space-y-2 text-sm"><div><dt className="subtle">固定工程配置</dt><dd className="break-words">{build.engineering_configuration.name} · v{build.engineering_configuration.revision}</dd></div><div><dt className="subtle">固定制造配置</dt><dd className="break-words">{build.manufacturing_configuration.name} · v{build.manufacturing_configuration.revision}</dd></div><div><dt className="subtle">计划数量</dt><dd className="min-w-0 [overflow-wrap:anywhere]">{decimalText(build.planned_quantity)} {build.unit}</dd></div><div><dt className="subtle">计划时间（UTC）</dt><dd className="break-words">{build.planned_start ? utcText(build.planned_start) : "开始未知"} ～ {build.planned_end ? utcText(build.planned_end) : "结束未知"}</dd></div><div><dt className="subtle">验证目标</dt><dd className="whitespace-pre-wrap break-words">{build.verification_objectives}</dd></div><div><dt className="subtle">实物处置要求</dt><dd className="whitespace-pre-wrap break-words">{build.disposition_plan}</dd></div>{build.previous_build_id && <div><dt className="subtle">前一轮</dt><dd>{builds.find(item => item.id === build.previous_build_id)?.name ?? "固定前轮（当前不可读）"}</dd></div>}</dl><Readiness build={build} materialNames={materialNames}/><p className="subtle">当前仅核对本轮固定配置。后续资源或供应变化需要独立快照路径，尚未启用。</p><Button variant="outline" disabled={!editable || build.owner_id !== principalId || build.source_status === "needs_recheck" || build.engineering_configuration.source_status === "needs_recheck" || build.manufacturing_configuration.source_status === "needs_recheck"} onClick={() => compute(build)}><ClipboardText/>{build.readiness ? "核对并读取已有结果" : "计算并保存准备缺项"}</Button>{build.owner_id !== principalId && <p className="subtle">本轮准备计算由负责人处理。</p>}<details><summary className="cursor-pointer text-sm">查看本轮固定配置</summary><div className="mt-3 grid min-w-0 gap-4 sm:grid-cols-2"><div className="min-w-0"><p className="mb-2 font-medium">工程配置</p><DetailValue value={build.engineering_configuration} sourceNames={sourceNames}/></div><div className="min-w-0"><p className="mb-2 font-medium">制造配置</p><DetailValue value={build.manufacturing_configuration} sourceNames={sourceNames}/></div></div></details></article>)}</div></section>
        <details className="panel"><summary className="cursor-pointer font-semibold">可见配置与版本记录</summary><div className="mt-4 space-y-5">{([ ["BOM", configurations.boms], ["工程配置", configurations.engineering], ["制造配置", configurations.processes] ] as const).map(([title, records]) => <section key={title} className="min-w-0"><h3 className="font-medium">{title} · {records.length} 版</h3>{records.length === 0 && <p className="subtle">尚无可见记录。</p>}<div className="mt-2 space-y-3">{records.map(item => <details key={item.id} className="min-w-0 rounded-lg border border-border p-3"><summary className="cursor-pointer break-words">{item.name} · v{item.revision} · 草稿</summary><div className="mt-3"><DetailValue value={item} sourceNames={sourceNames}/></div></details>)}</div></section>)}</div></details>
      </div>
    </div>
    <dialog ref={dialog} className="!w-[min(760px,calc(100vw-32px))] max-h-[90vh] overflow-auto" onCancel={event => { event.preventDefault(); if (!busy) closePreview(); }}>{preview && <div className="min-w-0 space-y-4"><h2 className="text-lg font-semibold">一次确认：{preparationNames[preview.command.operation]}</h2><p className="whitespace-pre-wrap break-words">{preview.review.effect}</p><p className="text-sm">本次负责人：当前本人。可见范围：{preview.review.visibility === "category" ? "品类授权成员" : "仅本人"}。</p>{preview.command.operation === "build.create" && <p className="text-sm">前轮关系：{typeof (preview.command.payload as Record<string, unknown>).previous_build_id === "string" ? builds.find(build => build.id === (preview.command.payload as Record<string, unknown>).previous_build_id)?.name ?? "固定前轮，需要保持当前授权" : "无前轮关系"}</p>}<div className="min-w-0 rounded-lg border border-border p-3"><DetailValue value={preview.review} sourceNames={sourceNames}/></div><details className="min-w-0 rounded-lg border border-border p-3" open><summary className="cursor-pointer font-medium">核对实际提交的范围与原文</summary><div className="mt-3 min-w-0"><DetailValue value={preview.command.payload} sourceNames={sourceNames}/></div></details><p className="subtle">本次确认在 {utcText(preview.expires_at)} 前有效。返回编辑或刷新不会发布配置、授权开工或创建实际样件。</p><div className="flex flex-wrap justify-end gap-2"><Button variant="outline" disabled={busy} onClick={closePreview}>返回编辑</Button><Button disabled={busy || !!pending} onClick={() => void run({ stage: "execute", command: preview.command })}>确认保存此次范围</Button></div></div>}</dialog>
  </section>;
}
